		// Also handle cases where $i references non-existent capture groups
		numSubexp := e.NumSubexp()
		// First convert valid $i references to ${i}
		for idx := numSubexp; idx > 0; idx-- {
			dst = strings.ReplaceAll(dst, fmt.Sprintf("$%d", idx), fmt.Sprintf("${%d}", idx))
